typedef struct { int start; int end; } Interval;

int mergeIntervals(Interval a[], int n) {
  if (n == 0) return 0;
  for (int i = 0; i < n - 1; ++i) {
    for (int j = i + 1; j < n; ++j) {
      if (a[j].start < a[i].start) {
        Interval t = a[i]; a[i] = a[j]; a[j] = t;
      }
    }
  }
  int count = 0;
  for (int i = 1; i < n; ++i) {
    if (a[count].end >= a[i].start) {
      if (a[i].end > a[count].end) a[count].end = a[i].end;
    } else {
      ++count;
      a[count] = a[i];
    }
  }
  return count + 1;
}

