int hasThreeSum(int arr[], int n, int target) {
  for (int i = 0; i < n - 2; ++i) {
    for (int j = i + 1; j < n - 1; ++j) {
      for (int k = j + 1; k < n; ++k) {
        if (arr[i] + arr[j] + arr[k] == target)
          return 1;
      }
    }
  }
  return 0;
}

int longestConsecutive(int arr[], int n) {
  int best = 0;
  for (int i = 0; i < n; ++i) {
    int len = 1, next = arr[i] + 1;
    int exists = 1;
    while (exists) {
      exists = 0;
      for (int j = 0; j < n; ++j) {
        if (arr[j] == next) {
          exists = 1;
          ++len;
          ++next;
          break;
        }
      }
    }
    if (len > best) best = len;
  }
  return best;
}

int majorityElement(int arr[], int n) {
  int candidate = 0, count = 0;
  for (int i = 0; i < n; ++i) {
    if (count == 0) candidate = arr[i];
    count += (arr[i] == candidate) ? 1 : -1;
  }
  count = 0;
  for (int i = 0; i < n; ++i)
    if (arr[i] == candidate) ++count;
  return count > n / 2 ? candidate : -1;
}

int minJumps(int arr[], int n) {
  if (n <= 1) return 0;
  int jumps = 0, end = 0, far = 0;
  for (int i = 0; i < n - 1; ++i) {
    if (i + arr[i] > far) far = i + arr[i];
    if (i == end) {
      ++jumps;
      end = far;
      if (end >= n - 1) return jumps;
    }
  }
  return -1;
}

int largestRectangle(int h[], int n) {
  int best = 0;
  for (int i = 0; i < n; ++i) {
    int left = i, right = i;
    while (left > 0 && h[left - 1] >= h[i]) --left;
    while (right < n - 1 && h[right + 1] >= h[i]) ++right;
    int area = h[i] * (right - left + 1);
    if (area > best) best = area;
  }
  return best;
}

int maxCircularSum(int arr[], int n) {
  int total = arr[0], maxEnd = arr[0], minEnd = arr[0];
  int maxSum = arr[0], minSum = arr[0];
  for (int i = 1; i < n; ++i) {
    total += arr[i];
    maxEnd = arr[i] > maxEnd + arr[i] ? arr[i] : maxEnd + arr[i];
    minEnd = arr[i] < minEnd + arr[i] ? arr[i] : minEnd + arr[i];
    if (maxEnd > maxSum) maxSum = maxEnd;
    if (minEnd < minSum) minSum = minEnd;
  }
  if (maxSum < 0) return maxSum;
  int wrapped = total - minSum;
  return maxSum > wrapped ? maxSum : wrapped;
}

int lisLength(int arr[], int n) {
  int dp[n], best = 0;
  for (int i = 0; i < n; ++i) {
    dp[i] = 1;
    for (int j = 0; j < i; ++j)
      if (arr[j] < arr[i] && dp[j] + 1 > dp[i]) dp[i] = dp[j] + 1;
    if (dp[i] > best) best = dp[i];
  }
  return best;
}

int maxSubarray(int arr[], int n) {
  int current = arr[0], best = arr[0];
  for (int i = 1; i < n; ++i) {
    current = current + arr[i] > arr[i] ? current + arr[i] : arr[i];
    if (current > best) best = current;
