void productExceptSelf(int a[], int out[], int n) {
  int prefix = 1, suffix = 1;
  for (int i = 0; i < n; ++i) {
    out[i] = prefix;
    prefix *= a[i];
  }
  for (int i = n - 1; i >= 0; --i) {
    out[i] *= suffix;
    suffix *= a[i];
  }
}

typedef struct { int start, end; } Interval;
void mergeIntervals(Interval a[], int n, Interval out[], int *m) {
  *m = 0;
  for (int i = 0; i < n; ++i) {
    if (*m == 0 || a[i].start > out[*m - 1].end) out[(*m)++] = a[i];
    else if (a[i].end > out[*m - 1].end) out[*m - 1].end = a[i].end;
  }
}

double medianTwo(int a[], int n, int b[], int m) {
  int i = 0, j = 0, prev = 0, cur = 0;
  for (int k = 0; k <= (n + m) / 2; ++k) {
    prev = cur;
    if (i < n && (j >= m || a[i] <= b[j])) cur = a[i++];
    else cur = b[j++];
  }
  if ((n + m) % 2) return cur;
  return (prev + cur) / 2.0;
}

int minCoins(int coins[], int n, int amount) {
  int dp[amount + 1];
  for (int i = 0; i <= amount; ++i) dp[i] = amount + 1;
  dp[0] = 0;
  for (int a = 1; a <= amount; ++a)
    for (int i = 0; i < n; ++i)
      if (coins[i] <= a && dp[a - coins[i]] + 1 < dp[a])
        dp[a] = dp[a - coins[i]] + 1;
  return dp[amount] > amount ? -1 : dp[amount];
}

int rob(int a[], int n) {
  int prev2 = 0, prev1 = 0;
  for (int i = 0; i < n; ++i) {
    int take = prev2 + a[i];
    int skip = prev1;
    int best = take > skip ? take : skip;
    prev2 = prev1;
    prev1 = best;
  }
  return prev1;
}

void flood(char g[][100], int r, int c, int rows, int cols) {
  if (r < 0 || c < 0 || r >= rows || c >= cols || g[r][c] != '1') return;
  g[r][c] = '0';
  flood(g, r + 1, c, rows, cols);
  flood(g, r - 1, c, rows, cols);
  flood(g, r, c + 1, rows, cols);
  flood(g, r, c - 1, rows, cols);
}
int islands(char g[][100], int rows, int cols) {
  int count = 0;
  for (int r = 0; r < rows; ++r)
    for (int c = 0; c < cols; ++c)
      if (g[r][c] == '1') { ++count; flood(g, r, c, rows, cols); }
  return count;
}

typedef struct Node { int value; struct Node *next; } Node;
int hasCycle(Node *head) {
  Node *slow = head, *fast = head;
  while (fast && fast->next) {
    slow = slow->next;
    fast = fast->next->next;
    if (slow == fast) return 1;
  }
  return 0;
}

typedef struct Node { int value; struct Node *next; } Node;
Node *reverseRecursive(Node *head) {
  if (!head || !head->next) return head;
  Node *newHead = reverseRecursive(head->next);
  head->next->next = head;
  head->next = NULL;
  return newHead;
}

