typedef struct TreeNode { int value; struct TreeNode *left; struct TreeNode *right; } TreeNode;
int validBST(TreeNode *root, long low, long high) {
  if (!root) return 1;
  if (root->value <= low || root->value >= high) return 0;
  return validBST(root->left, low, root->value) &&
         validBST(root->right, root->value, high);
}

typedef struct TreeNode { int value; struct TreeNode *left; struct TreeNode *right; } TreeNode;
TreeNode *lca(TreeNode *root, int a, int b) {
  if (!root || root->value == a || root->value == b) return root;
  TreeNode *left = lca(root->left, a, b);
  TreeNode *right = lca(root->right, a, b);
  if (left && right) return root;
  return left ? left : right;
}

void topoSort(int g[][100], int n, int order[]) {
  int indeg[100] = {0}, q[100], front = 0, back = 0, k = 0;
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j) if (g[i][j]) ++indeg[j];
  for (int i = 0; i < n; ++i) if (!indeg[i]) q[back++] = i;
  while (front < back) {
    int u = q[front++]; order[k++] = u;
    for (int v = 0; v < n; ++v)
      if (g[u][v] && --indeg[v] == 0) q[back++] = v;
  }
}

void shortestPath(int g[][100], int n, int src, int dist[]) {
  int q[100], front = 0, back = 0;
  for (int i = 0; i < n; ++i) dist[i] = -1;
  dist[src] = 0; q[back++] = src;
  while (front < back) {
    int u = q[front++];
    for (int v = 0; v < n; ++v)
      if (g[u][v] && dist[v] == -1) {
        dist[v] = dist[u] + 1;
        q[back++] = v;
      }
  }
}

void dijkstra(int g[][100], int n, int src, int dist[]) {
  int used[100] = {0};
  for (int i = 0; i < n; ++i) dist[i] = 1000000000;
  dist[src] = 0;
  for (int step = 0; step < n; ++step) {
    int u = -1;
    for (int i = 0; i < n; ++i)
      if (!used[i] && (u == -1 || dist[i] < dist[u])) u = i;
    if (u == -1 || dist[u] == 1000000000) break;
    used[u] = 1;
    for (int v = 0; v < n; ++v)
      if (g[u][v] >= 0 && dist[u] + g[u][v] < dist[v])
        dist[v] = dist[u] + g[u][v];
  }
}

int prim(int g[][100], int n) {
  int key[100], used[100] = {0}, total = 0;
  for (int i = 0; i < n; ++i) key[i] = 1000000000;
  key[0] = 0;
  for (int step = 0; step < n; ++step) {
    int u = -1;
    for (int i = 0; i < n; ++i)
      if (!used[i] && (u == -1 || key[i] < key[u])) u = i;
    used[u] = 1; total += key[u];
    for (int v = 0; v < n; ++v)
      if (!used[v] && g[u][v] > 0 && g[u][v] < key[v]) key[v] = g[u][v];
  }
  return total;
}

typedef struct Trie { struct Trie *child[26]; int end; } Trie;
