  Trie *cur = root;
  for (int i = 0; s[i]; ++i) {
    int k = s[i] - 'a';
    if (!cur->child[k]) return 0;
    cur = cur->child[k];
  }
  return 1;
}

void accessLRU(int cache[], int *size, int capacity, int key) {
  int pos = -1;
  for (int i = 0; i < *size; ++i)
    if (cache[i] == key) { pos = i; break; }
  if (pos != -1) {
    for (int i = pos; i < *size - 1; ++i) cache[i] = cache[i + 1];
    --(*size);
  }
  if (*size == capacity) {
    for (int i = 0; i < *size - 1; ++i) cache[i] = cache[i + 1];
    --(*size);
  }
  cache[(*size)++] = key;
}
